#!/usr/bin/env node
/**
 * Pulls traffic + subscriber + revenue snapshots into ops/metrics/<date>.json
 * so every agent sees the same numbers.
 *
 * - Cloudflare Web Analytics → page views, unique visitors (last 24h, last 7d)
 * - Worker /api/admin/stats → subscriber count, feedback count
 *
 * Required env:
 *   CLOUDFLARE_API_TOKEN — same token already in GH Actions Secrets
 *   CLOUDFLARE_ACCOUNT_ID
 *   ADMIN_TOKEN — Worker admin token (was generated by deploy-worker)
 *   SITE_HOST  — defaults to realdailyreview.com
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';

const OUT_DIR = path.resolve('ops/metrics');
const SITE_HOST = process.env.SITE_HOST || 'realdailyreview.com';

async function fetchAdminStats(adminToken) {
  if (!adminToken) return null;
  try {
    const r = await fetch(`https://${SITE_HOST}/api/admin/stats`, {
      headers: { Authorization: `Bearer ${adminToken}` },
    });
    if (!r.ok) return { error: `admin/stats ${r.status}` };
    return await r.json();
  } catch (err) {
    return { error: err.message };
  }
}

async function fetchCloudflareAnalytics({ token, accountId }) {
  // Cloudflare GraphQL Analytics API for Web Analytics (rumPageloadEventsAdaptiveGroups).
  if (!token || !accountId) return null;
  const since = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
  const until = new Date().toISOString();
  const query = `query GetRum($accountTag: String!, $since: Time!, $until: Time!) {
    viewer {
      accounts(filter: { accountTag: $accountTag }) {
        rumPageloadEventsAdaptiveGroups(
          filter: { date_geq: "${since.slice(0,10)}", date_leq: "${until.slice(0,10)}" }
          limit: 100
          orderBy: [date_DESC]
        ) {
          dimensions { date }
          sum { visits }
          count
        }
      }
    }
  }`;
  try {
    const r = await fetch('https://api.cloudflare.com/client/v4/graphql', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ query, variables: { accountTag: accountId, since, until } }),
    });
    if (!r.ok) return { error: `graphql ${r.status}: ${await r.text()}` };
    const j = await r.json();
    if (j.errors) return { error: JSON.stringify(j.errors).slice(0, 400) };
    const groups = j.data?.viewer?.accounts?.[0]?.rumPageloadEventsAdaptiveGroups || [];
    return {
      daily: groups.map((g) => ({ date: g.dimensions.date, visits: g.sum?.visits ?? 0, pageviews: g.count ?? 0 })),
    };
  } catch (err) {
    return { error: err.message };
  }
}

async function main() {
  await fs.mkdir(OUT_DIR, { recursive: true });
  const today = new Date().toISOString().slice(0, 10);

  const adminStats = await fetchAdminStats(process.env.ADMIN_TOKEN);
  const cf = await fetchCloudflareAnalytics({
    token: process.env.CLOUDFLARE_API_TOKEN,
    accountId: process.env.CLOUDFLARE_ACCOUNT_ID,
  });

  const snapshot = {
    fetched_at: new Date().toISOString(),
    site: SITE_HOST,
    subscribers: adminStats?.subscribers_by_status ?? null,
    subscribers_added_last_24h: adminStats?.subscribers_added_last_24h ?? 0,
    subscribers_with_phone: adminStats?.subscribers_with_phone ?? 0,
    feedback_total: adminStats?.feedback_total ?? 0,
    cloudflare_web_analytics: cf,
    admin_error: adminStats?.error,
  };
  const file = path.join(OUT_DIR, `${today}.json`);
  await fs.writeFile(file, JSON.stringify(snapshot, null, 2), 'utf8');
  console.log(`[traffic-stats] wrote ${file}`);

  // Also update a rolling latest.json
  await fs.writeFile(path.join(OUT_DIR, 'latest.json'), JSON.stringify(snapshot, null, 2), 'utf8');
}

main().catch((err) => { console.error(err); process.exit(1); });
